/// <summary>
///
/// </summary>
public static void createFromLinesRecord(MobPostOrderPromptOverrideLines _lines)
{
    MobPostOrderPromptOverrideLineFields    fields;
    MapEnumerator                           fieldsFromType = MobPostOrderPromptOverrideLineFields::getMapFromType(_lines.InputType,0).getEnumerator();

    delete_from fields where fields.LinesRecId == _lines.RecId;
    while(fieldsFromType.moveNext())
    {

        fields.FieldName = fieldsFromType.currentKey();
        fields.Value = fieldsFromType.currentValue();
        fields.LinesRecId = _lines.RecId;
        if (fields.FieldName != 'id' && fields.FieldName != 'name' && fields.FieldName != 'inputType')
        {
            fields.insert();
        }
    }

}

public static Map getMapFromType(TFMInputTypes _inputTypes, int _id, str _name = 'name', str _header = 'header', str _label = 'label', str _helpText = 'helpText', str _defaultValue = 'Value1', str _steps = 'Value1;Value2;etc')
{
    Map retMap;
    switch ( _inputTypes)
    {
        case TFMInputTypes::Date :
            retMap = TFMRegistrationCollectorDate::DateStepMap(true,_id,_name,_header,_label,_helpText,dateNull(),dateMax());
            break;
        case TFMInputTypes::Decimal :
            retMap = TFMRegistrationCollectorDecimal::DecimalStepMap(_id,_name,_header,_label, _helpText);
            break;
        case TFMInputTypes::Image :
            retMap = TFMRegistrationCollectorImage::ImageStepMap(_id,_name,_label,_header,'path');
            break;
        case TFMInputTypes::ImageCapture :
            retMap = TFMRegistrationCollectorImageCapture::ImageCaptureStepMap(_id,_name,_label,_header,'');
            break;
        case TFMInputTypes::Information :
            retMap = TFMRegistrationCollectorInformation::InformationStepMap(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::Integer :
            retMap = TFMRegistrationCollectorInteger::IntegerStepMap(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::List :
            retMap = TFMRegistrationCollectorList::ListStepMap(true,_id,_name,_label,_header, _helpText,_steps);
            break;
        case TFMInputTypes::MultiLineText :
            retMap = TFMRegistrationCollectorMultiLine::MultiLineStepMap(_id,_name,_label,_header, _helpText,'');
            break;
        case TFMInputTypes::MultiScan :
            retMap = TFMRegistrationCollectorMultiScan::MultiScanStepMap(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::QuantityByScan :
            retMap = TFMRegistrationCollectorQuantityByScan::QtyByScanStepMap(_id,_name,_label,_header, _helpText,_steps);
            break;
        case TFMInputTypes::RadioButton :
            retMap = TFMRegistrationCollectorRadioButton::RadioButtonStepMap(_id,_name,_label,_header, _helpText,_defaultValue,_steps);
            break;
        case TFMInputTypes::Signature :
            retMap = TFMRegistrationCollectorSignature::SignatureStepMap(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::Text :
            retMap = TFMRegistrationCollectorText::TextStepMap(true,_id,_name,_label,_header, _helpText,100);
            break;
        case TFMInputTypes::TypeAndQuantity :
            retMap = TFMRegistrationCollectorTypeAndQuantity::TypeAndQuantityMap(_id,_name,_label,_header, _helpText);
            break;
    }
    return retMap;
}
